PAGE = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#0c1324\">\n<title>مستكشف مجتمعات الجامعات | Campus Community Finder</title>\n<style>\n:root{--bg:#0b1221;--card:#142038;--accent:#8067ef;--text:#f2f5fc;--sub:#9fb0c8;--border:#293b58}\n*{box-sizing:border-box}\nbody{background:radial-gradient(ellipse at 85% 0%,#242446 0%,transparent 38%),var(--bg);color:var(--text);font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;margin:0;line-height:1.75}\nmain{max-width:1100px;margin:auto;padding:clamp(16px,4vw,42px)}\nheader{padding:34px 0 22px}\n.eyebrow{letter-spacing:2px;font-weight:700;color:#ae9cff;font-size:12px}\nh1{font-size:clamp(28px,4.4vw,46px);margin:5px 0 8px;line-height:1.45}\nh2{margin:5px 0;font-size:22px}\np{margin:4px 0;color:var(--sub)}\n.panel{background:linear-gradient(130deg,#172740,#101b30);border:1px solid var(--border);border-radius:22px;padding:clamp(16px,3vw,28px);box-shadow:0 10px 30px #0002}\nform{display:flex;flex-wrap:wrap;gap:12px;margin:14px 0}\ninput,select,button{font:inherit;border-radius:12px;outline:0}\ninput,select{background:#0f1a2e;color:#f5f7ff;border:1px solid #3f5375;padding:13px 16px;min-height:52px}\ninput:focus,select:focus{border-color:#a494ff;box-shadow:0 0 0 3px #8067ef25}\ninput{flex:1 1 340px;min-width:0}\nbutton{background:linear-gradient(125deg,#8e70ff,#644bdf);border:0;color:white;font-weight:700;padding:12px 24px;cursor:pointer;min-height:52px}\nbutton:disabled{opacity:.55;cursor:not-allowed}\nbutton.alt{background:#233554;border:1px solid #405472}\nsmall{color:#9caec6}\n.muted{font-size:14px}\n.progress-panel{display:none;margin-top:16px}\n.progress-head{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:15px}\n.progress-shell{height:13px;border-radius:30px;background:#263654;overflow:hidden;margin:12px 0}\n.progress-fill{background:linear-gradient(90deg,#51a8f3,#9d72fa);height:100%;width:0%;border-radius:30px;transition:width .3s ease}\n.aux{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}\n.chip{background:#253754;color:#d6e6ff;border:1px solid #395175;border-radius:999px;padding:3px 11px;font-size:13px;max-width:100%;overflow-wrap:anywhere}\n.stats{display:flex;gap:18px;flex-wrap:wrap;margin:18px 0;color:#d3def2}\n.stat strong{font-size:22px;color:white}\n.result-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:28px 0 14px}\n.filters{display:flex;gap:7px;overflow-x:auto;padding:7px 0 14px;scrollbar-width:thin}\n.filter{white-space:nowrap;min-height:38px;background:#1a2a43;border:1px solid #334664;border-radius:50px;padding:6px 14px;font-size:14px}\n.filter.active{background:#604ed7;border-color:#8f82ff}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:14px}\n.card{border:1px solid #31405b;background:#14213a;padding:18px;border-radius:18px;display:flex;flex-direction:column;gap:10px;overflow-wrap:anywhere}\n.tags{display:flex;gap:6px;flex-wrap:wrap}\n.tag{display:inline-flex;border-radius:7px;padding:3px 9px;font-size:12px;background:#283e5c;color:#bcd5ff}\n.tag.checked{background:#183e3a;color:#9ff1c3}\n.tag.pending{background:#43351f;color:#f7d18d}\n.card h3{font-size:18px;line-height:1.5;margin:0}\n.card p{flex:1;font-size:14px}\n.card a{color:#a6ceff;text-decoration:none}\n.card .visit{display:block;margin-top:7px;background:#263a5d;padding:9px 12px;border-radius:10px;text-align:center;font-weight:700}\n.card .source{font-size:12px;overflow-wrap:anywhere}\n.empty{border:1px dashed #42526e;background:#101c30;padding:36px 16px;text-align:center;border-radius:17px}\nfooter{padding:32px 0;color:#899db9;font-size:13px}\n#stop{display:none}\n#export{display:none}\n@media(max-width:580px){header{padding-top:14px}h1{font-size:29px}form button{flex:1} .card{padding:15px}}\n\n/* Public discussion archive: separate from actual community invitations */\n.archive-section{margin-top:26px}\n.archive-tools{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}\n.archive-tools input{flex:2 1 250px}.archive-tools select{flex:1 1 190px}\n.archive-meta{font-size:14px;color:var(--sub);margin-bottom:10px}\n#archiveMore{margin:18px auto;display:block}\n#archiveSection[hidden]{display:none}\n.archive-thread{border-right:3px solid #7e65e9}\n.archive-thread .visit{background:#243859}\n.archive-thread small{font-size:12px}\n.archive-header-count{font-size:15px;color:#c5b9ff}\n</style>\n</head>\n<body><main>\n<header>\n<div class=\"eyebrow\">CAMPUS COMMUNITY FINDER · v2</div>\n<h1>🔎 مستكشف مجتمعات طلاب الجامعات</h1>\n<p>اكتب اسم الجامعة بأي لغة، وسنبحث عن الاختصار والأسماء البديلة وروابط النقاشات العامة في مختلف المنصات.</p>\n</header>\n<section class=\"panel\">\n<form id=\"form\">\n<input id=\"university\" maxlength=\"110\" aria-label=\"اسم الجامعة\" value=\"جامعة محمد بن زايد للذكاء الاصطناعي\" placeholder=\"اكتب اسم الجامعة بالعربية أو الإنجليزية\" required>\n<select id=\"mode\" aria-label=\"نوع البحث\"><option value=\"deep\" selected>بحث معمّق</option><option value=\"quick\">بحث سريع</option></select>\n<button id=\"submit\" type=\"submit\">ابدأ البحث</button>\n<button id=\"stop\" class=\"alt\" type=\"button\">إيقاف</button>\n</form>\n<p class=\"muted\">يتم احتساب التقدم بعدد الاستعلامات المكتملة، وليس عدد صفحات الإنترنت. يمكن أن تتوقف مصادر عامة بسبب حدود الاستخدام.</p>\n<div id=\"progress\" class=\"progress-panel\" aria-live=\"polite\">\n<div class=\"progress-head\"><strong id=\"stage\">اكتشاف أسماء الجامعة...</strong><strong id=\"percent\">0%</strong></div>\n<div class=\"progress-shell\"><div id=\"fill\" class=\"progress-fill\"></div></div>\n<div class=\"stats\"><div class=\"stat\"><strong id=\"found\">0</strong> نتائج</div><div class=\"stat\"><strong id=\"completed\">0/0</strong> استعلامات</div></div>\n<div id=\"aliases\" class=\"aux\"></div>\n<p id=\"notices\" class=\"muted\"></p>\n</div>\n</section>\n<section>\n<div class=\"result-head\"><div><h2>المجموعات والنقاشات المكتشفة</h2><p id=\"subtitle\" class=\"muted\">ستظهر النتائج تدريجيًا أثناء البحث.</p></div><button id=\"export\" class=\"alt\" type=\"button\">تصدير CSV</button></div>\n<div id=\"filters\" class=\"filters\"></div>\n<div id=\"cards\" class=\"cards\"><div class=\"empty\">ابدأ البحث لتظهر النتائج مع مصادرها ودرجة التحقق منها.</div></div>\n</section>\n<section id=\"archiveSection\" class=\"panel archive-section\" hidden>\n<div class=\"result-head\"><div>\n<h2>📚 أرشيف نقاشات الطلاب <span id=\"archiveCount\" class=\"archive-header-count\"></span></h2>\n<p class=\"muted\">منشورات مفهرسة في مجتمع Reddit الخاص بالجامعة، وليست مجموعات دعوة مستقلة. لم يُفحص كل رابط بشكل منفرد.</p>\n</div><button id=\"archiveDownload\" type=\"button\" class=\"alt\">تنزيل جميع الروابط CSV</button></div>\n<div class=\"archive-tools\">\n<input id=\"archiveQuery\" placeholder=\"ابحث داخل النقاشات عن قبول، منحة، مقابلة...\" aria-label=\"بحث ضمن أرشيف النقاشات\">\n<select id=\"archiveTopic\" aria-label=\"تصنيف النقاشات\">\n<option value=\"all\">جميع المواضيع</option>\n<option value=\"groups\">مجموعات وتواصل الطلاب</option>\n<option value=\"admission\">القبول والنتائج</option>\n<option value=\"interviews\">المقابلات والاختبارات</option>\n<option value=\"funding\">المنح والتمويل</option>\n<option value=\"graduate\">الماجستير والدكتوراه</option>\n<option value=\"research\">التدريب والبحث العلمي</option>\n<option value=\"campus\">السكن والحياة الجامعية</option>\n</select></div>\n<p id=\"archiveMeta\" class=\"archive-meta\"></p>\n<div id=\"archiveCards\" class=\"cards\"></div>\n<button type=\"button\" id=\"archiveMore\" class=\"alt\">عرض 20 نقاشًا إضافيًا</button>\n</section>\n<footer>المصادر علنية فقط. علامة «تم فحص صفحة الدعوة» لا تعني الانضمام الفعلي أو الاطلاع على المحادثات الخاصة. مجموعات واتساب لا يمكن التأكد من صلاحية دعواتها دون فتحها عبر التطبيق.</footer>\n</main>\n<script>\nconst byId=id=>document.getElementById(id);\nlet es=null,items=new Map(),filter='الكل',running=false,diagnostics=[];\nconst knownPlatforms=['الكل','Telegram','WhatsApp','Discord','Reddit','Facebook','Instagram','X','Threads','Snapchat','TikTok','YouTube','Web','Community'];\nfunction escapeText(value){return String(value??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction verifiedTitle(v){\nif(v==='invite-page-verified')return 'فُحصت صفحة الدعوة';\nif(v==='public-community')return 'مجتمع عام';\nif(v==='public-link-unverified')return 'رابط منشور في مصدر طلابي';\nif(v==='linked-unverified')return 'دعوة مذكورة في مصدر آخر';\nreturn 'مرشح من البحث العام';\n}\nfunction drawFilters(){\nconst available=knownPlatforms.filter(p=>p==='الكل'||[...items.values()].some(x=>x.platform===p));\nbyId('filters').innerHTML=available.map(p=>'<button type=\"button\" class=\"filter '+(p===filter?'active':'')+'\" data-filter=\"'+escapeText(p)+'\">'+escapeText(p)+'</button>').join('');\nbyId('filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;drawFilters();drawCards()});\n}\nfunction drawCards(){\nlet rows=[...items.values()].sort((a,b)=>(b.score||0)-(a.score||0));\nif(filter!=='الكل')rows=rows.filter(x=>x.platform===filter);\nconst text=rows.map(x=>{\nconst clean=String(x.url||'');\nconst status=verifiedTitle(x.verification);\nconst checked=['invite-page-verified','public-community'].includes(x.verification);\nconst badge=checked?'checked':x.verification==='public-link-unverified'?'pending':'';\nconst source=String(x.source||x.url);\nconst sourceUrl=/^https:\\/\\/[^ ]+$/i.test(source)?source:clean;\nreturn '<article class=\"card\"><div class=\"tags\"><span class=\"tag\">'+escapeText(x.platform)+'</span><span class=\"tag '+badge+'\">'+escapeText(status)+'</span></div><h3>'+escapeText(x.title)+'</h3><p>'+escapeText(x.snippet||x.kind)+'</p><div class=\"source\">المصدر: <a href=\"'+escapeText(sourceUrl)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+escapeText(sourceUrl)+'</a></div><a class=\"visit\" href=\"'+escapeText(clean)+'\" target=\"_blank\" rel=\"noopener noreferrer\">فتح الرابط</a></article>';\n}).join('');\nbyId('cards').innerHTML=text||'<div class=\"empty\">لا توجد نتائج ضمن هذا التصنيف حتى الآن.</div>';\nbyId('export').style.display=items.size?'inline-block':'none';\n}\nfunction onEvent(event){\nconst d=JSON.parse(event.data);\nif(d.type==='aliases'){\nbyId('aliases').innerHTML=d.aliases.map(a=>'<span class=\"chip\">'+escapeText(a)+'</span>').join('');\nbyId('stage').textContent='اكتشاف أسماء الجامعة واختصاراتها';\nbyId('completed').textContent='0/'+(d.total||0);\n}else if(d.type==='result'){\nitems.set(d.item.url,d.item);\nbyId('found').textContent=items.size;\ndrawFilters();drawCards();\n}else if(d.type==='progress'){\nconst percentage=d.total?Math.round(100*d.completed/d.total):0;\nbyId('fill').style.width=percentage+'%';\nbyId('percent').textContent=percentage+'%';\nbyId('completed').textContent=d.completed+'/'+d.total;\nbyId('stage').textContent=d.stage;\nbyId('found').textContent=d.found;\nif(d.partial)byId('notices').textContent='بعض محركات البحث لم تستجب؛ تُعرض نتائج المصادر المتاحة.';\n}else if(d.type==='done'){\nbyId('fill').style.width='100%';byId('percent').textContent='100%';\nbyId('stage').textContent='اكتمل البحث في المصادر المتاحة';\nbyId('subtitle').textContent=d.found+' نتيجة بعد إزالة التكرار. تظهر حالة التحقق لكل نتيجة.';\nif(d.partial)byId('notices').textContent='انتهى البحث مع تعذّر بعض الاستعلامات ('+d.errors.length+' مصادر أو استعلامات موضحة). قد توجد مجموعات غير مفهرسة.';\nif(es){es.close();es=null}finish();\n}else if(d.type==='error'){\nbyId('notices').textContent=d.message||'تعذّر تنفيذ البحث';\nif(es){es.close();es=null}finish();\n}\n}\nfunction finish(){running=false;byId('submit').disabled=false;byId('stop').style.display='none'}\nfunction start(){\nconst u=byId('university').value.trim();if(u.length<2)return;\nif(es)es.close();\nitems.clear();filter='الكل';diagnostics=[];running=true;\nloadArchive(u);\nbyId('submit').disabled=true;byId('stop').style.display='inline-block';\nbyId('progress').style.display='block';byId('fill').style.width='0%';\nbyId('percent').textContent='0%';byId('stage').textContent='بدء التحليل...';\nbyId('aliases').innerHTML='';byId('found').textContent='0';byId('completed').textContent='0/0';\nbyId('notices').textContent='';byId('subtitle').textContent='تظهر النتائج فور العثور عليها...';\ndrawFilters();drawCards();\nconst url='/api/search/stream?university='+encodeURIComponent(u)+'&mode='+encodeURIComponent(byId('mode').value);\nes=new EventSource(url);\nes.onmessage=evt=>{try{onEvent(evt)}catch(err){console.error(err)}};\nes.onerror=()=>{if(!running)return;byId('notices').textContent='انقطع الاتصال أثناء البحث. النتائج المكتشفة محفوظة في الصفحة. يمكنك إعادة المحاولة.';if(es){es.close();es=null}finish()};\n}\nbyId('form').onsubmit=e=>{e.preventDefault();start()};\nbyId('stop').onclick=()=>{if(es){es.close();es=null}byId('stage').textContent='أُوقف عرض البحث';finish()};\nbyId('export').onclick=()=>{\nconst cols=['platform','title','url','snippet','source','verification'];\nconst rows=[cols,...[...items.values()].map(x=>cols.map(k=>x[k]||''))];\nconst csv='\\uFEFF'+rows.map(r=>r.map(v=>'\"'+String(v).replace(/\"/g,'\"\"')+'\"').join(',')).join('\\r\\n');\nconst blob=new Blob([csv],{type:'text/csv;charset=utf-8'});\nconst a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='campus-communities.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);\n};\n\nlet archiveRows=[],archiveOffset=20;\nfunction archiveCategory(item) {\n const s=(String(item.title||'')+' '+String(item.description||'')).toLowerCase();\n if(/discord|whatsapp|telegram|group for|student group|community|connect|server/.test(s)) return 'groups';\n if(/interview|exam|screening|assessment|test/.test(s))return 'interviews';\n if(/scholarship|stipend|tuition|financial|funding/.test(s))return 'funding';\n if(/phd|doctoral|masters|master's|msc|m\\.s\\.|graduate degree/.test(s))return 'graduate';\n if(/ugrip|internship|research lab|research proposal|research internship/.test(s))return 'research';\n if(/housing|accommodation|dorm|living|student life|campus|food/.test(s))return 'campus';\n return 'admission';\n}\nfunction archiveFiltered(){\n const q=byId('archiveQuery').value.trim().toLowerCase(),topic=byId('archiveTopic').value;\n return archiveRows.filter(x=>(topic==='all'||archiveCategory(x)===topic)&&\n (!q||(x.title+' '+x.description).toLowerCase().includes(q)));\n}\nfunction drawArchive(){\n const selected=archiveFiltered(),page=selected.slice(0,archiveOffset);\n byId('archiveCount').textContent='('+archiveRows.length+' رابطًا)';\n byId('archiveMeta').textContent='عرض '+page.length+' من '+selected.length+' نقاش مفهرس — المصدر: r/MBZUAI';\n const names={groups:'مجموعات وتواصل',admission:'قبول واستفسارات',interviews:'مقابلات واختبارات',\n funding:'منح وتمويل',graduate:'دراسات عليا',research:'بحث وتدريب',campus:'حياة جامعية'};\n byId('archiveCards').innerHTML=page.map(x=>{\n  const kind=archiveCategory(x),link=String(x.url||'');\n  return '<article class=\"card archive-thread\"><div class=\"tags\"><span class=\"tag\">Reddit</span><span class=\"tag\">'+escapeText(names[kind])+'</span><span class=\"tag pending\">رابط مفهرس غير متحقق فرديًا</span></div>'+\n '<h3>'+escapeText(x.title)+'</h3><p>'+escapeText(x.description||'مناقشة عامة')+'</p>'+\n '<a class=\"visit\" href=\"'+escapeText(link)+'\" target=\"_blank\" rel=\"noopener noreferrer\">فتح النقاش</a></article>';\n }).join('')||'<div class=\"empty\">لا توجد نقاشات مطابقة للبحث الحالي.</div>';\n byId('archiveMore').style.display=page.length<selected.length?'block':'none';\n}\nasync function loadArchive(university){\n byId('archiveSection').hidden=true;archiveRows=[];archiveOffset=20;\n try{\n   const res=await fetch('/api/archive?university='+encodeURIComponent(university));\n   if(!res.ok)return;\n   const obj=await res.json();\n   if(!obj.results||!obj.results.length)return;\n   archiveRows=obj.results.filter(x=>/^https:\\/\\/www\\.reddit\\.com\\/r\\/MBZUAI\\/comments\\//.test(x.url));\n   if(!archiveRows.length)return;\n   byId('archiveSection').hidden=false;\n   drawArchive();\n }catch(e){console.warn('Public archive unavailable',e)}\n}\nbyId('archiveQuery').addEventListener('input',()=>{archiveOffset=20;drawArchive()});\nbyId('archiveTopic').addEventListener('change',()=>{archiveOffset=20;drawArchive()});\nbyId('archiveMore').addEventListener('click',()=>{archiveOffset+=20;drawArchive()});\nbyId('archiveDownload').addEventListener('click',()=>{\n const cols=['platform','type','title','url','description','verification'];\n const rows=[cols,...archiveRows.map(x=>cols.map(k=>x[k]||''))];\n const csv='\\uFEFF'+rows.map(row=>row.map(v=>'\"'+String(v).replace(/\"/g,'\"\"')+'\"').join(',')).join('\\r\\n');\n const b=new Blob([csv],{type:'text/csv;charset=utf-8'});\n const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='MBZUAI_public_student_discussions.csv';a.click();\n setTimeout(()=>URL.revokeObjectURL(a.href),2000);\n});\n\ndrawFilters();\nloadArchive(byId('university').value);\n</script>\n</body></html>"
